package ktanesolver.module.modded.regular.unorderedkeys;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.unorderedkeys.UnorderedKeysInput.*;import ktanesolver.module.modded.regular.unorderedkeys.UnorderedKeysOutput.Action;
class UnorderedKeysSolverTest{@Test void pressesAKeyWhoseValueMatchesRemainingCount(){List<Key>keys=new ArrayList<>();for(int p=0;p<6;p++){int label=0;for(int l=1;l<=6;l++)if(UnorderedKeysSolver.rank(new Key(true,Color.RED,Color.RED,l),p)==p+1){label=l;break;}keys.add(new Key(true,Color.RED,Color.RED,label));}ModuleEntity m=new ModuleEntity();var out=(SolveSuccess<UnorderedKeysOutput>)new UnorderedKeysSolver().solve(new RoundEntity(),new BombEntity(),m,new UnorderedKeysInput(0,keys));assertThat(out.output().targetValue()).isEqualTo(6);assertThat(out.output().validPositions()).containsExactly(6);assertThat(out.output().twitchCommand()).isEqualTo("press 6");assertThat(m.getState()).containsKey("unorderedKeysStage1");}@Test void secondNecessaryResetSolves(){List<Key>keys=new ArrayList<>();keys.add(new Key(true,Color.RED,Color.RED,5));for(int p=1;p<6;p++)keys.add(new Key(false,null,null,null));var out=(SolveSuccess<UnorderedKeysOutput>)new UnorderedKeysSolver().solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new UnorderedKeysInput(1,keys));assertThat(out.output().action()).isEqualTo(Action.RESET);assertThat(out.output().twitchCommand()).isEqualTo("press 0");assertThat(out.solved()).isTrue();}}
